(function(){
const REV="2026-10-02";
const COMP="https://www.comptia.org/en-us/certifications/security/";
const PM="https://www.professormesser.com/security-plus/sy0-701/sy0-701-video/";
const P=function(s,q,o){ return {s:s,q:q,o:o}; };
const V=function(slug){ return PM+slug+"-sy0-701/"; };
const L=window.LESSON_PILOTS=window.LESSON_PILOTS||{};

L[23]={id:"lesson.sec.23",day:23,v:1,reviewed:REV,status:"drafted",src:[COMP,V("secure-baselines"),V("hardening-targets"),V("securing-wireless-and-mobile"),V("wireless-security-settings"),V("application-security"),V("asset-management"),V("vulnerability-scanning"),V("threat-intelligence"),V("penetration-testing"),V("analyzing-vulnerabilities"),V("vulnerability-remediation")],
  title:"Hardening, assets, and vulnerability operations",
  subtitle:"Build an operations baseline for Alder Printworks, a fictional manufacturer with offices, Wi-Fi, and cloud apps.",
  sections:[
    {id:"baselines",type:"facets",title:"Secure baselines and hardening",lead:"A secure baseline is the approved starting point. Hardening applies it to each platform without breaking the workload.",note:"sec.secure-baselines",
     facets:[
      {id:"base",name:"Baseline",say:"A baseline is the standard build for a device or service type. It captures approved settings so the team can measure drift later.",example:"Alder's Windows laptop image already includes disk encryption, EDR, and restricted local admin rights.",tags:["Approved build","Drift check"]},
      {id:"surface",name:"Attack surface",say:"Hardening removes what the system does not need, such as default accounts, open services, or risky protocols.",example:"The print server has SMB enabled, but its old web admin portal is disabled because nobody uses it.",tags:["Disable defaults","Reduce exposure"]},
      {id:"platform",name:"Platform fit",say:"Servers, mobile devices, network gear, cloud workloads, and embedded devices need different hardening targets.",example:"Alder stages firmware changes on warehouse scanners because uptime matters more than on test laptops.",tags:["Fit the workload","Change windows"]}],
     caution:"Hardening is not a single checklist. The same setting that helps a laptop can break an embedded or industrial system.",
     practice:P("Alder's security lead wants every new laptop build compared to one approved image so drift is easy to spot six months later.","What is that approved image called?",
      [["A secure baseline",true,"A secure baseline is the approved starting configuration used to build and later compare systems."],
       ["A CVSS score",false,"CVSS rates the severity of a vulnerability. It does not define a build standard."],
       ["A penetration test plan",false,"A test plan checks security later; it is not the baseline configuration itself."]])},
    {id:"wireless",type:"compare",title:"Wireless and mobile operations",lead:"Wireless access and mobile management are related, but they solve different control problems. Select a column to compare.",note:"sec.wireless-mobile-controls",
     cols:[
      {id:"wifi",name:"Enterprise Wi-Fi",say:"Focuses on how the device joins the network. Secure designs use strong encryption and per-user or per-device authentication.",example:"Alder's office SSID uses 802.1X against a RADIUS server instead of one shared password."},
      {id:"mdm",name:"Mobile device management",say:"Focuses on what security policy the device must follow after enrollment.",example:"Alder's MDM requires a screen lock, approved apps, and remote wipe on tablets."},
      {id:"ownership",name:"Ownership model",say:"Focuses on who owns the device and how much personal use is allowed.",example:"Warehouse tablets are COPE, while executives may use BYOD phones with company apps in a managed container."}],
     rows:[["Primary question","How does it authenticate to Wi-Fi?","What controls stay on the device?","Who owns it and who sets limits?"],["Typical technology","WPA3 / 802.1X / RADIUS","Enrollment, policy, remote wipe","BYOD, COPE, CYOD"],["Common risk","Shared passwords or weak encryption","Unmanaged apps or lost devices","Blurry personal vs company responsibility"]],
     caution:"WPA3 strengthens Wi-Fi access, but it does not replace MDM controls on the device itself.",
     practice:P("Alder wants each employee to use their own network credentials for wireless access instead of a shared office passphrase.","Which change fits best?",
      [["Move the SSID to 802.1X with RADIUS",true,"802.1X with RADIUS authenticates each user or device individually, unlike one shared preshared key."],
       ["Only deploy MDM remote wipe",false,"Remote wipe manages the device after enrollment. It does not replace Wi-Fi authentication."],
       ["Switch every phone to BYOD",false,"Ownership model does not solve the shared Wi-Fi password problem."]])},
    {id:"apps",type:"steps",title:"Application security review",lead:"Alder's small customer portal is being updated. Walk through the controls the team checks before release.",note:"cmp.sast-dast",
     steps:[
      {id:"code",name:"Inspect the code",say:"Use SAST and code review to catch unsafe functions, secrets, and obvious logic flaws before deployment.",example:"The pipeline flags a hardcoded API token and an unsanitized SQL query."},
      {id:"runtime",name:"Test the running app",say:"Use DAST and functional testing against a live build to find exposed responses and runtime weaknesses.",example:"Security testing finds a session cookie missing the Secure attribute in staging."},
      {id:"trust",name:"Sign and package",say:"Code signing helps prove the software came from the expected publisher and was not altered.",example:"The updater rejects a package whose signature no longer matches the published release."},
      {id:"contain",name:"Limit the blast radius",say:"Sandboxing and least privilege reduce damage if the application is exploited later.",example:"The portal worker account can write only to one upload directory, not the whole server."}],
     practice:P("Alder wants to find risky functions in the source before the build is ever deployed to staging.","Which testing approach fits first?",
      [["SAST",true,"SAST analyzes code or binaries without running the application, so it fits early pipeline review."],
       ["DAST",false,"DAST needs the application to be running so it can probe behavior from the outside."],
       ["Penetration testing",false,"Penetration testing is broader and later. It is not the first code-focused check described here."]])},
    {id:"assets",type:"map",title:"Where assets are in the lifecycle",lead:"Security operations follows assets from purchase to disposal. Place each example in the right stage.",note:"sec.asset-lifecycle",
     zones:[
      {id:"acquire",name:"Acquire and assign",desc:"Buying, receiving, and assigning ownership"},
      {id:"use",name:"Inventory and retain",desc:"Tracking assets and following retention rules"},
      {id:"retire",name:"Sanitize or destroy",desc:"Removing data and safely retiring media"}],
     items:[
      {id:"po",zone:"acquire",kind:"Record",name:"New switch purchase order",say:"Procurement and ownership records start the asset's security trail.",example:"Alder records who requested the switch and which site will own it."},
      {id:"tag",zone:"use",kind:"Control",name:"Inventory tag and owner",say:"An accurate inventory ties the asset to a location, owner, and update plan.",example:"A switch in the warehouse is tagged to the network team and maintenance window."},
      {id:"retain",zone:"use",kind:"Rule",name:"Retention schedule",say:"Data and media stay available for the required business or legal period.",example:"Alder keeps print-job logs for the period defined in customer contracts."},
      {id:"wipe",zone:"retire",kind:"Action",name:"Sanitize SSD before reuse",say:"Sanitization clears recoverable data before the asset is reassigned or recycled.",example:"Alder uses an approved wipe process before reissuing a laptop."},
      {id:"destroy",zone:"retire",kind:"Evidence",name:"Certificate of destruction",say:"Physical destruction and proof matter when sensitive media leaves control.",example:"A shredding vendor returns a certificate for failed drives from finance laptops."}],
     links:["Inventory is not just a spreadsheet; it gives accountability for patching, risk exceptions, and disposal approval.","Retention affects data as well as devices. Security teams need to know what must stay and what may be destroyed.","Sanitization removes data for reuse; destruction makes the media itself unusable."],
     practice:P("Alder is retiring old finance laptop drives and needs proof the data cannot be recovered afterward.","What should the team keep?",
      [["A certificate of destruction",true,"When media is physically destroyed, the certificate documents that the disposal requirement was met."],
       ["Only the original purchase order",false,"Procurement records prove ownership, not that the drive's data was made unrecoverable."],
       ["A new Wi-Fi heat map",false,"A heat map relates to wireless coverage, not disposal evidence."]])},
    {id:"vuln",type:"facets",title:"Vulnerability management cycle",lead:"Alder's weekly program mixes scans, intelligence, and validation instead of treating one scanner report as the whole answer.",note:"sec.vulnerability-management-cycle",
     facets:[
      {id:"identify",name:"Identify",say:"Scans, pen tests, bug reports, and threat intelligence reveal possible weaknesses from different viewpoints.",example:"Alder's scanner finds missing patches while a threat feed says one flaw is being exploited in the wild.",tags:["Scans","Intel","Tests"]},
      {id:"analyze",name:"Analyze",say:"Analysts confirm what is real, link the issue to the right asset, and use CVE and CVSS data to prioritize response.",example:"A reported web flaw is dismissed as a false positive because that application is not installed.",tags:["CVE","CVSS","False positive"]},
      {id:"respond",name:"Remediate and validate",say:"Teams patch, reconfigure, segment, or apply compensating controls, then rescan or review logs to verify the fix.",example:"Alder blocks public access to a cloud storage bucket, then reruns the check to confirm it is closed.",tags:["Patch","Compensating control","Rescan"]}],
     caution:"A low CVSS score can still matter if the asset is exposed or already targeted. Severity is one input, not the whole decision.",
     practice:P("Alder's scanner says a Linux kernel flaw exists on a Windows file server.","How should the analyst classify that result first?",
      [["A false positive",true,"The reported flaw does not match the software on the asset, so the finding is reported but not real."],
       ["A false negative",false,"A false negative is a real issue the scanner missed, not a bogus finding it reported."],
       ["A validated exploit",false,"Nothing in the scenario shows the server is actually vulnerable or exploited."]])},
    {id:"check",type:"check",title:"Check yourself",lead:"Hardening and vulnerability scenarios without the lesson in view. These count as scored practice.",from:[23],max:6}
  ]};

L[24]={id:"lesson.sec.24",day:24,v:1,reviewed:REV,status:"drafted",src:[COMP,V("security-monitoring"),V("security-tools"),V("firewalls"),V("web-filtering"),V("operating-system-security"),V("secure-protocols"),V("email-security"),V("monitoring-data"),V("endpoint-security")],
  title:"Monitoring and enterprise security capabilities",
  subtitle:"Alder Printworks now needs signal, visibility, and enforcement across email, endpoints, and network paths.",
  sections:[
    {id:"monitor",type:"facets",title:"Security monitoring workflow",lead:"Monitoring is useful only if collection, triage, tuning, and retention all work together.",note:"sec.security-monitoring-workflow",
     facets:[
      {id:"collect",name:"Collect centrally",say:"Aggregate logs and alerts from systems that matter so patterns do not stay isolated on one host.",example:"Alder forwards firewall, VPN, and endpoint alerts to one console.",tags:["Aggregation","Visibility"]},
      {id:"triage",name:"Triage fast",say:"Analysts decide whether the alert is benign, suspicious, or urgent enough for containment.",example:"A ransomware alert from a kiosk is escalated faster than a single blocked phishing email.",tags:["Severity","Prioritization"]},
      {id:"tune",name:"Tune over time",say:"Noisy rules burn analyst attention. Tuning improves signal without blinding the team.",example:"A rule that triggers on every software update is narrowed to unsigned installers only.",tags:["False positives","Noise reduction"]},
      {id:"retain",name:"Keep useful history",say:"Archived data supports trend review, audits, and later investigations when the initial event was missed.",example:"Alder reviews six months of VPN logs after a contractor account issue is discovered.",tags:["Archiving","Investigation"]}],
     practice:P("Alder's analysts see thousands of low-value alerts every Monday when normal patching begins.","What should they improve first?",
      [["Alert tuning",true,"Tuning reduces expected noise so analysts can focus on events that matter."],
       ["Log deletion",false,"Deleting logs removes evidence and does not solve the bad alert logic."],
       ["More shared passwords",false,"Shared passwords weaken security and are unrelated to alert volume."]])},
    {id:"tools",type:"compare",title:"Telemetry and assessment tools",lead:"These tools all produce security data, but they answer different questions. Select a column to compare.",note:"sec.telemetry-and-assessment-tools",
     cols:[
      {id:"siem",name:"SIEM",say:"Collects and correlates logs and events from many systems to spot patterns and trigger alerts.",example:"Alder's SIEM links a suspicious VPN login to unusual file access and an endpoint alert."},
      {id:"scap",name:"SCAP",say:"Standardizes automated configuration and vulnerability checks across systems.",example:"Alder uses SCAP-aligned checks to compare server settings against a secure benchmark."},
      {id:"netflow",name:"NetFlow",say:"Summarizes traffic metadata such as source, destination, protocol, and bytes transferred.",example:"Alder confirms that a design workstation sent gigabytes to an unknown external IP overnight."}],
     rows:[["Best for","Cross-source correlation","Automated security assessment","Traffic pattern summaries"],["Shows full packet content?","No","No","No"],["Common question","Is this activity related?","Does this host match policy?","Who talked to whom, and how much?"],["Typical blind spot","Needs good source coverage","Less useful without defined baselines","No payload or file contents"]],
     practice:P("Alder needs to know which internal host sent large amounts of data to an external address, but it does not need packet payloads.","Which source is the best fit?",
      [["NetFlow",true,"NetFlow records connection metadata and traffic volume without requiring full packet capture."],
       ["A certificate of destruction",false,"That documents media disposal, not network traffic."],
       ["A password vault",false,"A vault controls secrets, not flow visibility."]])},
    {id:"controls",type:"map",title:"Operational controls by job",lead:"Several enterprise tools may appear in the same environment. Match each one to the job it does best.",note:"sec.security-operations-tooling",
     zones:[
      {id:"host",name:"At the host",desc:"Controls that watch or enforce on the device itself"},
      {id:"edge",name:"At the boundary",desc:"Controls that influence traffic or content before it reaches the user"},
      {id:"behavior",name:"Across patterns",desc:"Controls that reason over trends and anomalies"}],
     items:[
      {id:"fim",zone:"host",kind:"Control",name:"File integrity monitoring",say:"Tracks sensitive files for unauthorized changes.",example:"Alder alerts when system binaries on its Windows print server change overnight."},
      {id:"av",zone:"host",kind:"Control",name:"Antivirus and anti-malware",say:"Scans files and processes for known malicious behavior or signatures.",example:"An endpoint agent quarantines a downloader dropped from email."},
      {id:"dlp",zone:"edge",kind:"Control",name:"Data loss prevention",say:"Inspects content movement to prevent sensitive data from leaving allowed channels.",example:"Alder blocks an email that contains a batch of customer tax IDs."},
      {id:"filter",zone:"edge",kind:"Control",name:"Web or DNS filtering",say:"Blocks destinations based on reputation, category, or policy.",example:"Alder prevents browsers from reaching newly registered domains used in phishing."},
      {id:"ueba",zone:"behavior",kind:"Analytics",name:"UEBA",say:"Learns normal behavior and flags anomalies across users or devices.",example:"Alder investigates an engineer who downloads far more files than usual at 2 a.m."},
      {id:"agent",zone:"host",kind:"Method",name:"Agent-based collection",say:"Places a collector on the endpoint for richer host detail.",example:"An EDR agent records the parent process of a suspicious PowerShell launch."}],
     links:["Agentless collection reaches more devices quickly, but it usually sees less host detail than an installed agent.","DLP cares about the content leaving the environment; web filtering cares about the destination being reached.","UEBA is strongest when it has enough history to tell normal from abnormal behavior."],
     practice:P("Alder wants an alert whenever core operating system files on a print server change outside the maintenance window.","Which tool is the closest fit?",
      [["File integrity monitoring",true,"FIM is designed to detect unexpected changes to watched files."],
       ["NetFlow",false,"NetFlow shows connection summaries, not local file changes."],
       ["DMARC",false,"DMARC helps email receivers evaluate mail, not server files."]])},
    {id:"rules",type:"steps",title:"Adjusting enterprise enforcement",lead:"Alder uses a simple process whenever security wants to tighten network and content controls.",note:"sec.firewall-and-web-filtering",
     steps:[
      {id:"need",name:"State the need",say:"Describe exactly which path, protocol, user group, or category should be allowed or denied.",example:"Security wants developers to use SSH to a bastion host, but nobody should use Telnet to any server."},
      {id:"scope",name:"Scope narrowly",say:"Prefer the smallest set of source, destination, port, and time conditions that meets the business need.",example:"Alder allows one subnet to reach one management host on 22 instead of opening all remote management traffic."},
      {id:"test",name:"Review side effects",say:"Check whether the rule conflicts with existing access, monitoring, or emergency support paths.",example:"A proposed block on file-sharing traffic is tested against the plant's label printers before deployment."},
      {id:"watch",name:"Monitor results",say:"After the change, confirm the block or allow behaves as expected and does not flood the team with false alarms.",example:"Alder confirms that malicious category hits drop while normal vendor support traffic still works."}],
     caution:"A broader rule is not better just because it is simpler. Specific rules are easier to review, justify, and reverse.",
     practice:P("Alder wants to stop outbound Telnet everywhere, but still allow administrators to manage servers securely.","Which access should remain open?",
      [["SSH on 22 to the approved management hosts",true,"SSH is the secure replacement for Telnet and should stay available where needed."],
       ["Any TCP port to any server",false,"That is too broad and defeats least privilege."],
       ["Telnet on 23 from the admin VLAN only",false,"Telnet still exposes credentials and session traffic in cleartext."]])},
    {id:"email",type:"facets",title:"Email and endpoint response",lead:"Email authentication stops obvious spoofing, and endpoint detection tells the team what happened after a message lands.",note:"sec.email-and-endpoint-detection",
     facets:[
      {id:"spf",name:"SPF",say:"Publishing which mail servers may send for your domain helps receivers detect unauthorized senders.",example:"Alder lists its cloud mail provider in SPF so lookalike senders fail the check.",tags:["Authorized senders"]},
      {id:"dkim",name:"DKIM",say:"A cryptographic signature lets the receiver verify the message came through an approved sender and was not altered.",example:"Alder's outbound mail gateway signs messages before delivery.",tags:["Message integrity"]},
      {id:"dmarc",name:"DMARC",say:"A policy tells the receiver whether to monitor, quarantine, or reject mail that fails SPF or DKIM checks and where to send reports.",example:"Alder starts with p=none and later moves to reject after reviewing reports.",tags:["Policy","Reporting"]},
      {id:"edr",name:"EDR and XDR",say:"EDR investigates and contains endpoint events. XDR links that event with other signals such as email, identity, or network data.",example:"Alder traces a malicious attachment from the mailbox to the laptop process tree and blocked sign-in attempts.",tags:["Containment","Correlation"]}],
     practice:P("Alder wants receiving mail servers to reject messages that fail domain checks and send feedback reports to its administrators.","Which record is needed?",
      [["DMARC",true,"DMARC provides the receiver policy and reporting for SPF and DKIM outcomes."],
       ["WPA3",false,"WPA3 secures wireless access, not email authentication."],
       ["NetFlow",false,"NetFlow summarizes network traffic, not mail authentication policy."]])},
    {id:"check",type:"check",title:"Check yourself",lead:"Monitoring and enterprise-capability scenarios without the lesson in view. These count as scored practice.",from:[24],max:6}
  ]};

L[25]={id:"lesson.sec.25",day:25,v:1,reviewed:REV,status:"drafted",src:[COMP,V("identity-and-access-management"),V("access-controls"),V("multifactor-authentication"),V("password-security")],
  title:"Identity and access management",
  subtitle:"Alder Printworks is cleaning up account lifecycle, sign-in design, and privileged access for staff, contractors, and administrators.",
  sections:[
    {id:"lifecycle",type:"steps",title:"Provision, review, deprovision",lead:"Identity and access management starts with account lifecycle, not just sign-in screens.",note:"sec.identity-lifecycle",
     steps:[
      {id:"create",name:"Provision",say:"Create the identity, verify who it belongs to, and grant only the starting access the role needs.",example:"A new warehouse supervisor gets one account, MFA enrollment, and access only to scheduling and inventory tools."},
      {id:"change",name:"Update for movers",say:"When jobs change, old permissions are removed before new ones are added.",example:"A supervisor transferred to finance loses floor-management access the same day the finance role is assigned."},
      {id:"attest",name:"Attest and review",say:"Managers or owners periodically confirm the access still makes sense.",example:"Every quarter, application owners review contractor accounts that still have production access."},
      {id:"remove",name:"Deprovision",say:"When the need ends, disable sessions, remove group memberships, and revoke privileged paths immediately.",example:"Alder disables a terminated contractor's VPN, cloud account, and badge access before the exit meeting ends."}],
     practice:P("Alder learns that a contractor left last Friday but can still sign in today.","Which IAM activity failed?",
      [["Deprovisioning",true,"Deprovisioning should have removed or disabled access as soon as the work ended."],
       ["Federation",false,"Federation is a trust model between identity systems, not the offboarding action itself."],
       ["Password stretching",false,"Password security matters, but the direct failure is leaving the account active."]])},
    {id:"fed",type:"compare",title:"SSO, federation, and token protocols",lead:"These ideas work together, but the exam expects you to separate the user experience from the trust model and the protocol.",note:"cmp.saml-oauth-oidc",
     cols:[
      {id:"sso",name:"SSO",say:"One sign-in reaches many apps, reducing repeated prompts and password reuse.",example:"Alder staff sign in once each morning and open HR, print-queue, and timekeeping apps without reauthenticating."},
      {id:"fed",name:"Federation",say:"Separate identity systems trust each other so a home account works across organizational boundaries.",example:"Alder's print vendor signs in with the vendor's own account to reach one shared project portal."},
      {id:"proto",name:"SAML / OAuth / OIDC",say:"Protocols carry the authentication or authorization decision between systems.",example:"Alder's browser app uses SAML, while a mobile app uses OAuth with OpenID Connect for identity claims."}],
     rows:[["What it answers","How many sign-ins the user does","Who trusts whose identity system","How the token or assertion is carried"],["Scope","User experience","Cross-system trust","Implementation detail"],["Common trap","Assuming SSO always means federation","Assuming federation always means many apps","Mixing authentication and authorization"]],
     practice:P("Alder wants a mobile app to read a user's calendar without storing their password.","Which protocol family fits the authorization problem?",
      [["OAuth",true,"OAuth delegates access to the app through tokens instead of sharing the user's password."],
       ["MAC",false,"MAC is an access control model based on labels and clearances, not a federation protocol."],
       ["WPA3",false,"WPA3 secures wireless access, not application authorization."]])},
    {id:"models",type:"compare",title:"Access control models",lead:"Read what drives the decision: role, label, owner choice, or attributes.",note:"sec.access-control-models",
     cols:[
      {id:"rbac",name:"RBAC",say:"Permissions come from job roles such as payroll clerk or help desk technician.",example:"Everyone in Alder's shipping role can print labels and update delivery status."},
      {id:"abac",name:"ABAC",say:"Policies evaluate attributes such as department, device health, project, time, or location.",example:"Alder allows engineering designs only from managed laptops during business hours."},
      {id:"mac",name:"MAC and DAC",say:"MAC uses central labels and clearances; DAC lets the owner decide who gets access.",example:"Government drawings use labels, while a shared team folder lets the owner grant edit rights."}],
     rows:[["Decision basis","Job function","Policy attributes","Labels or owner choice"],["Best clue","Sales role, admin role, HR role","Device, time, location, department","Secret label or owner-managed share"],["Who controls it","Security or IAM admins","Policy authors and IAM","Central authority for MAC, object owner for DAC"]],
     caution:"Rule-based controls may look like ABAC, but the best exam answer usually depends on whether the prompt emphasizes attributes or fixed network-style rules.",
     practice:P("Alder grants access only if the user is in finance, on a managed laptop, and in the office during work hours.","Which model fits best?",
      [["ABAC",true,"The decision uses several attributes about the user, device, location, and time."],
       ["DAC",false,"DAC would let the resource owner decide directly rather than evaluating policy attributes."],
       ["MAC",false,"MAC is about central labels and clearances, not these dynamic conditions."]])},
    {id:"factors",type:"facets",title:"MFA and factor choice",lead:"Not every two-step process is MFA. The factor categories matter.",note:"sec.mfa-and-factors",
     facets:[
      {id:"know",name:"Something you know",say:"Passwords, PINs, or answers to questions are all knowledge factors.",example:"Alder's kiosk asks for a password and a six-digit memorized PIN.",tags:["Knowledge"]},
      {id:"have",name:"Something you have",say:"A phone authenticator, smart card, or security key adds possession.",example:"An admin taps a FIDO2 key after entering a password.",tags:["Possession"]},
      {id:"are",name:"Something you are",say:"Biometrics such as a fingerprint or face match the person.",example:"Alder's design lab laptops unlock with Windows Hello facial recognition.",tags:["Biometric"]},
      {id:"risk",name:"Choose stronger factors",say:"Phishing-resistant methods such as security keys or certificate-backed flows resist relay and replay better than one-time codes alone.",example:"Alder moves administrators from SMS codes to security keys.",tags:["Phishing resistant"]}],
     practice:P("An Alder user signs in with a password and then a second memorized PIN.","Does that count as MFA?",
      [["No, both are knowledge factors",true,"Two knowledge secrets are still one factor type, so the sign-in is not multifactor authentication."],
       ["Yes, because there are two prompts",false,"The number of prompts does not matter if both prompts use the same factor category."],
       ["Yes, because the PIN is shorter",false,"Length does not change the factor type. It is still something the user knows."]])},
    {id:"privileged",type:"facets",title:"Passwords, passwordless, and PAM",lead:"Normal users need strong, usable credentials; administrators need tighter handling of privileged access.",note:"sec.password-and-pam",
     facets:[
      {id:"pw",name:"Password practice",say:"Long, unique passwords paired with a manager beat short, reused passwords with arbitrary changes.",example:"Alder issues a password manager so staff can stop reusing the same phrase across SaaS tools.",tags:["Length","Uniqueness"]},
      {id:"less",name:"Passwordless",say:"Passwordless sign-in reduces phishing and reset volume by replacing shared secrets with stronger factors.",example:"Executives use passkeys for the travel portal instead of a memorized password.",tags:["Reduced phishing","Usability"]},
      {id:"pam",name:"Privileged access management",say:"PAM stores privileged secrets, rotates them, and grants elevation only when needed.",example:"Alder's domain admin password is checked out briefly from a vault and rotated when the task ends.",tags:["Vaulting","Just in time"]}],
     caution:"PAM is not just a password safe. It is about controlling, auditing, and shortening privileged access.",
     practice:P("Alder wants domain admins to request elevation only for short maintenance windows, with their secrets rotated after use.","Which control is the best fit?",
      [["Privileged access management",true,"PAM handles vaulting, rotation, and just-in-time privileged access."],
       ["A public guest Wi-Fi SSID",false,"Wireless segmentation does not control administrative credentials."],
       ["DMARC enforcement",false,"DMARC protects mail receivers from spoofed email. It does not manage admin secrets."]])},
    {id:"check",type:"check",title:"Check yourself",lead:"IAM scenarios without the lesson in view. These count as scored practice.",from:[25],max:6}
  ]};

L[26]={id:"lesson.sec.26",day:26,v:1,reviewed:REV,status:"drafted",src:[COMP,V("scripting-and-automation"),V("incident-response"),V("incident-planning"),V("digital-forensics"),V("log-data")],
  title:"Automation, incident response, forensics, and data sources",
  subtitle:"Alder Printworks now needs repeatable response, defensible evidence handling, and better investigation habits.",
  sections:[
    {id:"auto",type:"facets",title:"Automation and SOAR",lead:"Automation is powerful because it is repeatable. It is risky for the same reason.",note:"sec.automation-and-soar",
     facets:[
      {id:"tasks",name:"Repeatable tasks",say:"Provisioning, ticket creation, alert enrichment, and basic containment are common automation targets.",example:"Alder opens a ticket, pulls the host owner, and isolates the device when ransomware telemetry scores high.",tags:["Repeatable","Fast response"]},
      {id:"soar",name:"SOAR playbooks",say:"SOAR links tools and response actions into one workflow instead of making an analyst swivel between consoles.",example:"One phishing playbook checks the sender, searches other mailboxes, and queues a quarantine action.",tags:["Orchestration","Workflow"]},
      {id:"guards",name:"Guardrails",say:"Good automation has scopes, approvals, and rollback paths so mistakes do not spread instantly.",example:"Alder requires analyst approval before any playbook disables a user account.",tags:["Approvals","Safety"]}],
     practice:P("Alder wants confirmed phishing alerts to automatically open a ticket, gather sender details, and prepare a mailbox search in one workflow.","What capability is closest?",
      [["SOAR",true,"SOAR orchestrates multiple tools and response steps into one workflow."],
       ["CVSS",false,"CVSS rates vulnerability severity, not workflow automation."],
       ["DAC",false,"DAC is an access control model and does not automate operations."]])},
    {id:"ir",type:"steps",title:"Incident response sequence",lead:"Alder teaches responders to protect the business and the evidence in the right order.",note:"sec.incident-response-phases",
     steps:[
      {id:"prep",name:"Prepare",say:"Before incidents happen, define contacts, logging, tools, backups, and playbooks.",example:"Alder keeps an after-hours roster and tests endpoint isolation before an emergency."},
      {id:"detect",name:"Detect and analyze",say:"Confirm the event, estimate scope, and decide how serious it is.",example:"Analysts compare endpoint alerts with VPN logs to see whether one laptop or several accounts are involved."},
      {id:"contain",name:"Contain",say:"Limit further damage before removing the threat completely.",example:"Alder isolates one infected laptop from the network while preserving it for evidence collection."},
      {id:"eradicate",name:"Eradicate and recover",say:"Remove the cause, rebuild or restore systems, and return service safely.",example:"The malicious scheduled task is removed and the laptop is rebuilt from a known-good image."},
      {id:"learn",name:"Lessons learned",say:"Document what happened, what worked, and what must change next time.",example:"Alder adds a new email block rule and updates its phishing playbook after the incident review."}],
     caution:"Containment comes before eradication. If you wipe first, you may lose both evidence and control of the spread.",
     practice:P("Alder has confirmed ransomware on one laptop and wants to stop it from reaching file shares before rebuilding anything.","Which phase comes next?",
      [["Containment",true,"The team should limit further spread before eradication and recovery."],
       ["Lessons learned",false,"Lessons learned happens after the active response work is complete."],
       ["Eradication",false,"Eradication comes after the situation is contained."]])},
    {id:"evidence",type:"map",title:"Evidence and volatility",lead:"Investigators must preserve evidence and collect the most fragile data first.",note:"sec.order-of-volatility",
     zones:[
      {id:"volatile",name:"Collect first",desc:"Data most likely to disappear quickly"},
      {id:"stable",name:"Collect after",desc:"Data that normally survives longer"},
      {id:"process",name:"Preserve correctly",desc:"Documentation and legal handling around the evidence"}],
     items:[
      {id:"ram",zone:"volatile",kind:"Evidence",name:"RAM contents",say:"Memory can disappear at shutdown or reboot, so it is collected early.",example:"Alder captures memory from the suspect workstation before powering it down."},
      {id:"proc",zone:"volatile",kind:"Evidence",name:"Running processes and connections",say:"Live state helps explain what the malware was doing in memory and on the network.",example:"Investigators note the active PowerShell process and its open connection before isolation."},
      {id:"disk",zone:"stable",kind:"Evidence",name:"Disk image",say:"A forensic image preserves the stored file system for later analysis.",example:"Alder creates a bit-level copy of the SSD and hashes it immediately."},
      {id:"logs",zone:"stable",kind:"Evidence",name:"Archived remote logs",say:"Remote logs often survive longer than the host itself, but they should still be preserved promptly.",example:"Alder exports firewall and identity logs covering the suspected time window."},
      {id:"custody",zone:"process",kind:"Record",name:"Chain of custody form",say:"This records who handled the evidence and when, preserving legal defensibility.",example:"Each person who transports the laptop signs the chain-of-custody record."},
      {id:"hold",zone:"process",kind:"Rule",name:"Legal hold",say:"A hold prevents relevant records from being deleted while legal review is pending.",example:"Alder's counsel directs IT to preserve the suspect user's mailbox and cloud drive."}],
     links:["The order of volatility exists because some evidence disappears on reboot or power loss.","Forensic handling is not just collection. Hashing, documentation, and chain of custody preserve trust in the evidence.","Remote logs can outlive the compromised host, which is why centralized logging helps investigations."],
     practice:P("Alder is about to power off a suspicious workstation that may contain malware only in memory.","What evidence should investigators try to collect first?",
      [["RAM contents",true,"Memory is more volatile than disk and may disappear as soon as power is lost."],
       ["The certificate of destruction",false,"Disposal paperwork is irrelevant during evidence collection."],
       ["The quarterly access review list",false,"That IAM document does not preserve the volatile state on the host."]])},
    {id:"logs",type:"compare",title:"Picking the right data source",lead:"Different log sources answer different parts of the investigation. Select a column to compare.",note:"sec.investigative-log-data",
     cols:[
      {id:"fw",name:"Firewall and network",say:"Show allowed or denied flows, source and destination addresses, and sometimes connection duration.",example:"Alder confirms the infected laptop reached one command-and-control address over HTTPS."},
      {id:"host",name:"Endpoint and OS",say:"Show processes, services, user logons, and local security events on the host.",example:"Alder finds the exact parent process that launched an encoded PowerShell command."},
      {id:"app",name:"Application and identity",say:"Show user actions inside applications and authentication outcomes.",example:"Alder sees the account authenticate from VPN and then access the document portal minutes later."}],
     rows:[["Best for","Path and connection questions","Execution and host-state questions","User-action and sign-in questions"],["Common blind spot","Little process context","Limited off-host visibility","May miss network path details"],["Typical follow-up","Correlate with host logs","Correlate with network or identity logs","Correlate with host or firewall logs"]],
     practice:P("Alder knows a malicious file was opened and wants to learn which parent process started the suspicious PowerShell child process.","Which source is most useful?",
      [["Endpoint or OS security logs",true,"Host logs and EDR telemetry are best for process trees and local execution context."],
       ["DMARC aggregate reports",false,"DMARC reports mail-authentication outcomes, not host process lineage."],
       ["A Wi-Fi site survey",false,"Coverage maps have nothing to do with process execution evidence."]])},
    {id:"check",type:"check",title:"Check yourself",lead:"Automation, incident, and forensic scenarios without the lesson in view. These count as scored practice.",from:[26],max:6}
  ]};

L[27]={id:"lesson.sec.27",day:27,v:1,reviewed:REV,status:"drafted",src:[COMP,V("secure-baselines"),V("security-monitoring"),V("identity-and-access-management"),V("incident-response")],
  title:"Review: Security operations",
  subtitle:"Short workplace cases across Levels 23 to 26. Use the guided review, then the independent check.",
  sections:[
    {id:"cases",type:"casebook",title:"Guided review",lead:"Each case connects an operations problem to the most relevant concept and section. These answers do not count toward your score.",
     cases:[
      {id:"c1",task:"Choose the missing control",s:"Alder's Linux web servers are rebuilt from scratch often, but each admin tweaks SSH, logging, and local firewall settings by hand. Six months later the servers no longer match each other.",q:"What would reduce this drift best?",
       o:[["A secure baseline",true,"A secure baseline gives one approved starting configuration that each rebuilt server can be compared against later."],["A DMARC record",false,"DMARC protects email receivers from spoofed mail. It does not standardize server builds."],["A legal hold",false,"A legal hold preserves data for legal review, not server configuration consistency."]],
       links:[{day:23,sec:"baselines",label:"Level 23: Secure baselines and hardening"},{concept:"sec.secure-baselines"}]},
      {id:"c2",task:"Separate the tools",s:"Security needs to know which workstation uploaded 8 GB to a new internet address overnight, but it does not need the packet payload.",q:"Which data source fits first?",
       o:[["NetFlow",true,"NetFlow summarizes who talked to whom and how much data moved without storing the packet contents."],["A certificate of destruction",false,"Disposal documentation does not explain a network transfer."],["A password vault",false,"A vault manages secrets, not traffic metadata."]],
       links:[{day:24,sec:"tools",label:"Level 24: Telemetry and assessment tools"},{concept:"sec.telemetry-and-assessment-tools"}]},
      {id:"c3",task:"Fix the lifecycle gap",s:"A contractor's account still works three days after the contract ended, even though the person returned the laptop and badge on time.",q:"Which IAM process failed?",
       o:[["Deprovisioning",true,"The account should have been disabled or removed as soon as the relationship ended."],["Federation",false,"Federation concerns trust between identity systems, not the offboarding action."],["Passwordless authentication",false,"Passwordless may improve sign-in strength, but the main failure is that the account still exists."]],
       links:[{day:25,sec:"lifecycle",label:"Level 25: Provision, review, deprovision"},{concept:"sec.identity-lifecycle"}]},
      {id:"c4",task:"Order the response",s:"Ransomware is actively encrypting a shared workstation. One responder wants to rebuild it immediately, while another wants to cut its network access first.",q:"Which action comes first in the incident process?",
       o:[["Contain the workstation",true,"Containment limits spread before eradication and recovery begin."],["Start lessons learned",false,"Lessons learned comes after the active response and recovery work."],["Rotate the domain admin vault password only",false,"That might be useful later, but it does not address the immediate sequencing problem described."]],
       links:[{day:26,sec:"ir",label:"Level 26: Incident response sequence"},{concept:"sec.incident-response-phases"}]},
      {id:"c5",task:"Read the protocol need",s:"Alder wants administrators to manage warehouse switches remotely, but leadership does not want credentials sent in cleartext across the network.",q:"Which protocol change best fits?",
       o:[["Use SSH instead of Telnet",true,"SSH encrypts the remote session and credentials, unlike Telnet."],["Use HTTP instead of HTTPS",false,"HTTP would reduce protection rather than improve it."],["Use POP3 instead of IMAP",false,"Those are mail retrieval protocols, not remote switch administration tools."]],
       links:[{day:24,sec:"rules",label:"Level 24: Adjusting enterprise enforcement"},{concept:"sec.secure-communications"}]},
      {id:"c6",task:"Preserve the right evidence",s:"Investigators suspect malware only in memory on a design workstation and are about to power it down for shipping to another site.",q:"What evidence should they try to collect before shutdown?",
       o:[["RAM contents",true,"Memory is volatile and may vanish when the system is powered off."],["The shredding vendor certificate",false,"That belongs to media disposal, not live forensics."],["Next quarter's access review roster",false,"That document does not preserve the volatile state on the workstation."]],
       links:[{day:26,sec:"evidence",label:"Level 26: Evidence and volatility"},{concept:"sec.order-of-volatility"}]}]},
    {id:"check",type:"check",title:"Independent check",lead:"Different scored scenarios drawn from Levels 23 to 26, with the lessons hidden. These count as scored practice.",from:[23,24,25,26],max:8}
  ]};

L[31]={id:"lesson.sec.31",day:31,v:1,reviewed:REV,status:"drafted",src:[COMP,V("firewalls"),V("secure-protocols"),V("monitoring-data"),V("log-data"),V("endpoint-security")],
  title:"PBQ drills: ports, logs, and firewall rules",
  subtitle:"Practice common Security+ PBQ patterns: secure protocol pairings, log-line interpretation, and top-down firewall evaluation.",
  sections:[
    {id:"workflow",type:"steps",title:"PBQ workflow for operations questions",lead:"A fast, repeatable process keeps PBQs from draining the clock.",note:"sec.firewall-rule-processing",
     steps:[
      {id:"read",name:"Read the prompt for scope",say:"Identify whether the task is asking for a port, the secure protocol, the attack name, or the rule outcome.",example:"A PBQ may show one log line, four protocols, and ask only which attack is most likely."},
      {id:"mark",name:"Match the obvious facts",say:"Map fixed facts first: known secure pairings such as SSH/22, HTTPS/443, LDAPS/636, or RDP/3389.",example:"If the question is remote administration, cross out Telnet before worrying about the port."},
      {id:"order",name:"Evaluate in sequence",say:"For firewall tables, read top to bottom because first match wins and unmatched traffic hits implicit deny.",example:"A broad deny above a narrow allow usually means the narrow rule never matters."},
      {id:"name",name:"Name the pattern",say:"For logs, look for the recognizable pattern before reading every token: brute force, spraying, SQLi, XSS, or traversal.",example:"One account with hundreds of failures suggests brute force even before you inspect the source IP."}],
     practice:P("A PBQ shows two rules: 1) deny any to server 23, 2) allow admin subnet to server 22. The prompt asks for the best remote admin protocol.","What should you notice first?",
      [["SSH on 22 is the secure management path",true,"The secure protocol pairing answers the question before the blocked Telnet rule matters."],
       ["Telnet on 23 is faster",false,"Telnet is not the secure option and is already denied."],
       ["POP3 on 110 is related",false,"POP3 is a mail retrieval protocol, not remote administration."]])},
    {id:"ports",type:"compare",title:"Common ports and secure pairings",lead:"These services are easy to confuse under time pressure. Compare them by job and whether the protocol is the secure choice.",note:"sec.web-mail-directory-ports",
     cols:[
      {id:"admin",name:"Remote administration",say:"SSH on 22 and RDP on 3389 are the common management answers. Telnet on 23 is the insecure distractor.",example:"A PBQ asks which protocol should replace Telnet on network gear: SSH is the secure answer."},
      {id:"webmail",name:"Web and mail",say:"HTTPS is 443. SMTP often appears as 25 or 587, while secure retrieval pairings include POP3S on 995 and IMAPS on 993.",example:"A secure mail-reader clue often points to IMAPS or POP3S instead of the older cleartext ports."},
      {id:"directory",name:"Directory and file sharing",say:"LDAP is 389, LDAPS is 636, and SMB file sharing is 445.",example:"A domain lookup or bind question that emphasizes encryption usually points to LDAPS on 636."}],
     rows:[["Secure web port","443","443","Not applicable"],["Secure replacement clue","SSH over Telnet","IMAPS/POP3S over IMAP/POP3","LDAPS over LDAP"],["Common distractor","23","25 for retrieval or 80 for secure web","389 when encryption matters"]],
     practice:P("A directory lookup must be encrypted in transit for a line-of-business app.","Which pairing fits best?",
      [["LDAPS on 636",true,"LDAPS is the secure LDAP variant and uses 636."],
       ["LDAP on 389",false,"389 is the standard LDAP port, but the prompt specifically requires encryption in transit."],
       ["RDP on 3389",false,"RDP is for remote desktop access, not directory queries."]])},
    {id:"clues",type:"map",title:"Map log clues to likely attacks",lead:"PBQs often ask you to infer the attack from one short clue. Place the clue with the best attack label.",note:"sec.log-attack-signatures",
     zones:[
      {id:"password",name:"Password attacks",desc:"Patterns involving repeated authentication failures"},
      {id:"web",name:"Web attacks",desc:"Suspicious request strings inside URLs or forms"},
      {id:"policy",name:"Behavior worth investigation",desc:"Events that are suspicious but need context"}],
     items:[
      {id:"bf",zone:"password",kind:"Clue",name:"500 failures on one account",say:"Many attempts against one account usually indicate brute force.",example:"The same admin username appears in every failed VPN entry."},
      {id:"spray",zone:"password",kind:"Clue",name:"One common password across many accounts",say:"A few common guesses spread across many usernames often indicates password spraying.",example:"Every user in finance gets one failed sign-in with Winter2027! from the same source."},
      {id:"sql",zone:"web",kind:"Clue",name:"' OR 1=1 --",say:"Boolean SQL fragments inside a request strongly suggest SQL injection.",example:"The login form submits a username that closes the quoted string and adds OR 1=1."},
      {id:"xss",zone:"web",kind:"Clue",name:"<script>alert(1)</script>",say:"Injected script tags in input or URLs suggest cross-site scripting.",example:"A search field request contains a script tag instead of a normal term."},
      {id:"trav",zone:"web",kind:"Clue",name:"../ or ..\\",say:"Path traversal strings try to break out of the intended directory.",example:"A file download request references ../../../../etc/passwd."},
      {id:"odd",zone:"policy",kind:"Clue",name:"Unexpected ports at odd hours",say:"Odd timing or destinations may not prove the attack type, but they are worth quick investigation.",example:"A kiosk initiates outbound connections on uncommon ports at 3 a.m."}],
     links:["Brute force usually means many attempts against one account. Spraying usually means one or a few passwords against many accounts.","Some clues name the attack directly, while others only tell you the event deserves investigation.","Read the pattern before the protocol. The same log line can include a harmless service port and a clearly malicious input string."],
     practice:P("A web access log includes GET /search?q=%3Cscript%3Ealert(1)%3C/script%3E.","Which attack does that most strongly suggest?",
      [["Cross-site scripting",true,"The encoded script tags in a user-controlled field are a classic XSS clue."],
       ["Password spraying",false,"Spraying would show repeated authentication attempts across many accounts, not an injected script in a request."],
       ["Chain of custody",false,"Chain of custody is a forensic handling record, not an attack type."]])},
    {id:"rules",type:"compare",title:"Reasoning about firewall tables",lead:"The key skill is usually evaluation order, not memorizing vendor syntax.",note:"sec.firewall-rule-processing",
     cols:[
      {id:"specific",name:"Specific allow above broad deny",say:"A narrow allow can work if it is read before the broader block that would otherwise catch it.",example:"Allow admins to SSH to one bastion first, then deny all other SSH."},
      {id:"broad",name:"Broad deny above narrow allow",say:"The deny shadows the later allow because first match wins.",example:"Deny all traffic to the server before an allow for the admin subnet means the allow is never reached."},
      {id:"implicit",name:"No match at all",say:"If traffic matches no earlier rule, the firewall falls to its implicit deny.",example:"A new backup path fails because no explicit allow exists for that destination and port."}],
     rows:[["Outcome","Works as intended","Later allow is shadowed","Traffic is blocked by default"],["Main clue","Order favors the exception","Order kills the exception","No rule fits"],["Best fix","Keep the order and scope tight","Move or narrow the deny","Add a precise allow if the path is legitimate"]],
     practice:P("A table reads: 1) deny any to web01 any, 2) allow admin subnet to web01 22. An admin tries SSH to web01.","What happens?",
      [["The SSH attempt is blocked by rule 1",true,"The broad deny matches first, so rule 2 is never evaluated."],
       ["The SSH attempt is allowed by rule 2",false,"Rule 2 would help only if it appeared before the broad deny."],
       ["The result depends on DMARC",false,"DMARC is an email policy and does not affect firewall processing."]])},
    {id:"check",type:"check",title:"Check yourself",lead:"Ports, logs, and firewall-order scenarios without the lesson in view. These count as scored practice.",from:[31],max:6}
  ]};
})();
